/* Recursos do Início, da Análise, do Hardware e da Manutenção. Cada um usa leitura real; sem dado, o cartão diz o que falta. */
(function () {
  const { add, helpers: H } = NexoFeatures;
  const bridge = desktopBridge;
  const HOUR = 3600e3;
  const DAY = 24 * HOUR;
  const LIMIT = /warning|critical|limit|threshold|shutdown|t\s*j\s*max/i;
  const temp = (v) => (H.fin(v) ? `${H.nf(v)} °C` : '--');
  const okTemp = (s) => s.type === 'Temperature' && H.fin(s.value) && s.value > 5 && s.value < 125 && !LIMIT.test(String(s.name));
  const gpuTypes = ['GpuNvidia', 'GpuAmd', 'GpuIntel'];
  const byType = (c, deviceTypes, sensorType, test = () => true) => c.sensors().filter((s) => (!deviceTypes || deviceTypes.includes(s.deviceType)) && s.type === sensorType && H.fin(s.value) && test(s));
  const lastActivity = (c, re) => c.activity.filter((a) => re.test(a.title)).sort((a, b) => b.timestamp - a.timestamp)[0] || null;
  const forecast = () => { try { return NexoBrain.forecastDisk(Nexo.store.brainHistory()); } catch { return null; } };
  // Por programa (processos de mesmo nome somados): o Claude ou o Chrome não aparecem três vezes na mesma lista.
  const topCpu = (c) => H.programs(c.src('processes'), 'cpu').filter((p) => !/^(idle|system|nexo.*|powershell|pwsh|conhost)$/i.test(p.name));
  const topMem = (c) => H.programs(c.src('processes'), 'memory').filter((p) => !/^(idle|system|memory compression|nexo.*)$/i.test(p.name));
  /** " em N processos" quando o programa tem mais de um processo somado. */
  const inProcesses = (p) => (p.count > 1 ? ` em ${p.count} processos` : '');
  const go = (view) => () => { Nexo.go(view); };
  const clickId = (id, view) => () => { if (view) { Nexo.go(view); } setTimeout(() => document.getElementById(id)?.click(), 120); };

  /* ======================= Início ======================= */
  add('home', [
    { id: 'cpu-pico-5m', icon: 'cpu', title: 'Pico do processador (5 min)', compute: (c) => { const v = H.vals(c.live, 'cpu'); if (!v.length) { return null; } const m = H.max(v); return { value: H.nf(m), unit: '%', detail: `Média de ${H.nf(H.avg(v))}% no mesmo período`, tone: H.tone(m, 85, 97), spark: v.slice(-90) }; } },
    { id: 'cpu-1h', icon: 'chart', title: 'Processador na última hora', compute: (c) => { const v = H.vals(c.since(HOUR), 'cpu'); if (v.length < 5) { return null; } return { value: H.nf(H.avg(v)), unit: '%', detail: `Média de ${v.length} minutos · pico de ${H.nf(H.max(v))}%`, spark: v }; } },
    { id: 'mem-livre', icon: 'mem', title: 'Memória livre agora', compute: (c) => { const s = c.snap; if (!s?.memoryTotalBytes) { return null; } const free = s.memoryTotalBytes - s.memoryUsedBytes; const share = free / s.memoryTotalBytes; return { value: H.bytes(free), detail: `${H.nf(share * 100)}% livre de ${H.bytes(s.memoryTotalBytes)} instalados`, bar: share, tone: H.tone(share, 0.2, 0.08, false) }; } },
    { id: 'mem-pico-24h', icon: 'mem', title: 'Pico de memória em 24 h', compute: (c) => { const h = c.since(DAY); const v = H.vals(h, 'memory'); if (v.length < 5) { return null; } const m = H.max(v); return { value: H.nf(m), unit: '%', detail: `às ${new Date(h.find((s) => s.memory === m)?.timestamp).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}`, tone: H.tone(m, 88, 96), spark: v.filter((_, i) => i % 10 === 0) }; } },
    { id: 'disco-livre', icon: 'disk', title: 'Livre no disco do sistema', compute: (c) => { const d = c.snap?.primaryDrive; if (!d?.sizeBytes) { return null; } const letter = d.driveLetter ? `${d.driveLetter}: · ` : ''; return { value: H.bytes(d.freeBytes), detail: `${letter}${H.nf(d.usedPercent)}% ocupado de ${H.bytes(d.sizeBytes)}`, bar: d.usedPercent / 100, tone: H.tone(d.usedPercent, 85, 95) }; } },
    { id: 'disco-cheio-em', icon: 'calendar', title: 'Disco cheio em', empty: 'Aprendendo', emptyDetail: 'Precisa de uns dias de histórico para prever.', compute: () => { const f = forecast(); if (!f) { return null; } if (!f.daysToFull) { return { value: 'Sem pressa', detail: `O uso cresce ${H.nf(Math.max(0, f.slopePerDay), 2)} ponto percentual por dia`, tone: 'good' }; } return { value: H.nf(f.daysToFull), unit: 'dias', detail: `No ritmo de ${H.nf(f.slopePerDay, 2)} ponto percentual por dia`, tone: H.tone(f.daysToFull, 30, 10, false) }; } },
    { id: 'temp-tendencia', icon: 'temp', title: 'Tendência da temperatura', compute: (c) => { const pts = c.live.map((s) => [s.timestamp / 60000, c.hottest(s)]).filter(([, v]) => H.fin(v)); if (pts.length < 8) { return null; } const slope = H.slope(pts); const [, now] = pts[pts.length - 1]; const word = slope > 0.6 ? 'Subindo' : slope < -0.6 ? 'Caindo' : 'Estável'; return { value: word, detail: `${temp(now)} agora · ${H.signed(slope, 1)} °C por minuto`, tone: slope > 1.5 ? 'warn' : 'good', spark: pts.map((p) => p[1]) }; } },
    { id: 'temp-max-hoje', icon: 'fire', title: 'Mais quente hoje', compute: (c) => { const start = new Date(); start.setHours(0, 0, 0, 0); const h = c.hist.filter((s) => s.timestamp >= start.getTime()); const v = h.map((s) => c.hottest(s)).filter(H.fin); if (!v.length) { return null; } const m = H.max(v); return { value: temp(m), detail: `Mínima do dia: ${temp(H.min(v))}`, tone: H.tone(m, 85, 95) }; } },
    { id: 'gpu-pico', icon: 'gpu', title: 'Pico da placa de vídeo (5 min)', empty: 'Sem sensor', compute: (c) => { const v = H.vals(c.live, 'gpu'); if (!v.length) { return null; } return { value: H.nf(H.max(v)), unit: '%', detail: `Média de ${H.nf(H.avg(v))}%`, spark: v.slice(-90) }; } },
    { id: 'clock-agora', icon: 'bolt', title: 'Velocidade do processador', empty: 'Sem sensor', emptyDetail: 'Depende do serviço de sensores.', compute: (c) => { const clock = c.deep.cpuClock; if (!H.fin(clock)) { return null; } const ratio = c.brain?.clockRatio?.(clock); return { value: H.nf(clock / 1000, 2), unit: 'GHz', detail: H.fin(ratio) ? `${H.nf(ratio * 100)}% do maior clock já visto` : 'Clock do núcleo mais rápido', bar: H.fin(ratio) ? ratio : undefined }; } },
    { id: 'rede', icon: 'wifi', title: 'Conexão de rede', compute: (c) => (c.snap ? { value: c.snap.networkConnected ? 'Conectado' : 'Sem rede', detail: c.snap.networkConnected ? 'Há um adaptador com endereço IPv4.' : 'Nenhum adaptador com endereço.', tone: c.snap.networkConnected ? 'good' : 'warn' } : null) },
    { id: 'reinicio', icon: 'history', title: 'Reiniciar ajudaria?', compute: (c) => { const up = c.snap?.uptimeSeconds; if (!H.fin(up)) { return null; } const days = up / 86400; return { value: days >= 7 ? 'Sim' : 'Não precisa', detail: `Ligado há ${H.dur(up)}${days >= 7 ? ': atualizações e vazamentos de memória se acumulam' : ''}`, tone: days >= 14 ? 'bad' : days >= 7 ? 'warn' : 'good' }; } },
    { id: 'estabilidade', icon: 'wave', title: 'Estabilidade da carga', compute: (c) => { const v = H.vals(c.live, 'cpu'); if (v.length < 10) { return null; } const sd = H.sd(v); return { value: sd < 8 ? 'Estável' : sd < 18 ? 'Oscilando' : 'Agitada', detail: `Variação de ±${H.nf(sd)} pontos nos últimos minutos`, tone: sd < 8 ? 'good' : sd < 18 ? 'warn' : 'bad', spark: v.slice(-60) }; } },
    { id: 'mais-pesa', icon: 'target', title: 'Programa que mais pesa agora', needs: ['processes'], empty: 'Medindo…', compute: (c) => { const top = topCpu(c); if (!top.length) { return null; } return { value: top[0].name, text: true, detail: `${H.nf(top[0].cpuPercent, 1)}% de CPU · ${H.bytes(top[0].memoryBytes)}${inProcesses(top[0])}`, list: top.slice(1, 3).map((p) => [p.name, `${H.nf(p.cpuPercent, 1)}%`]) }; } },
    { id: 'mais-memoria', icon: 'mem', title: 'Quem mais ocupa memória', needs: ['processes'], empty: 'Medindo…', compute: (c) => { const top = topMem(c); if (!top.length) { return null; } return { value: top[0].name, text: true, detail: `${H.bytes(top[0].memoryBytes)}${inProcesses(top[0])}`, list: top.slice(1, 3).map((p) => [p.name, H.bytes(p.memoryBytes)]) }; } },
    { id: 'lentidoes-24h', icon: 'pulse', title: 'Lentidões em 24 h', compute: (c) => { const e = c.brain?.recentEpisodes?.(DAY) || []; return { value: H.nf(e.length), detail: e.length ? `Última ${H.ago(e[0].end)}: ${{ cpu: 'CPU alta', memory: 'memória no limite', thermal: 'calor', throttle: 'queda de clock' }[e[0].kind] || e[0].kind}` : 'Nenhum episódio detectado', tone: e.length > 5 ? 'warn' : 'good' }; } },
    { id: 'aprendizado', icon: 'star', title: 'O quanto o Nexo já conhece', compute: (c) => { const l = c.brain?.learning?.(); if (!l) { return null; } return { value: H.nf(l.coverage), unit: '%', detail: `da sua semana · ${H.nf(l.minutes)} minutos observados`, bar: l.coverage / 100 }; } },
    { id: 'normal-agora', icon: 'target', title: 'Agora vs o seu normal', empty: 'Aprendendo', emptyDetail: 'Precisa de algumas semanas nesta hora.', compute: (c) => { const v = c.snap?.cpuUsage; const e = c.brain?.expected?.('cpu', Date.now()); if (!e || !H.fin(v)) { return null; } const z = (v - e.mean) / e.sd; return { value: z > 1.5 ? 'Acima' : z < -1.5 ? 'Abaixo' : 'Normal', detail: `Esperado nesta hora: ${H.nf(Math.max(0, e.mean - e.sd))}–${H.nf(Math.min(100, e.mean + e.sd))}% · agora ${H.nf(v)}%`, tone: z > 2 ? 'warn' : 'good' }; } },
    { id: 'ultima-limpeza', icon: 'broom', title: 'Última limpeza', compute: (c) => { const a = lastActivity(c, /limpeza/i); return a ? { value: H.ago(a.timestamp), detail: a.detail || a.title, tone: Date.now() - a.timestamp > 30 * DAY ? 'warn' : 'good' } : { value: 'Nunca', detail: 'A limpeza segura mostra uma prévia antes de apagar.', tone: 'warn' }; }, action: { label: 'Limpar', run: clickId('run-cleanup', 'optimize') } },
    { id: 'ultima-analise', icon: 'search', title: 'Última análise inteligente', compute: (c) => { const a = lastActivity(c, /análise/i); return a ? { value: H.ago(a.timestamp), detail: a.detail || '' } : { value: 'Nunca', detail: 'Leva poucos segundos.' }; }, action: { label: 'Analisar', run: go('analysis') } },
    { id: 'sessoes-semana', icon: 'game', title: 'Sessões nesta semana', compute: (c) => { const list = c.sessions.filter((s) => s.startedAt >= Date.now() - 7 * DAY); return { value: H.nf(list.length), detail: list.length ? `${H.dur(H.sum(H.vals(list, (s) => s.report?.meta?.durationS)))} observados` : 'Grave uma sessão enquanto joga.' }; }, action: { label: 'Ver', run: go('sessions') } },
    { id: 'diario-ativo', icon: 'book', title: 'Alterações ativas', compute: (c) => { const a = c.journal.filter((e) => e.status === 'applied' && e.reversible); return { value: H.nf(a.length), detail: a.length ? `Última: ${a[0].title}` : 'Nada alterado no sistema agora (limpezas não contam: não há o que desfazer).' }; }, action: { label: 'Diário', run: go('activity') } },
    { id: 'perfil', icon: 'user', title: 'Perfil de uso', compute: () => (Nexo.profile?.id ? { value: NexoProfiles.get(Nexo.profile.id)?.nome || Nexo.profile.id, text: true, detail: 'Muda a ênfase do índice e das dicas.' } : null), action: { label: 'Trocar', run: () => Nexo.chooseProfile?.() } },
    { id: 'energia', icon: 'plug', title: 'Fonte de energia', needs: ['power'], compute: (c) => { const p = c.src('power'); if (!p) { return null; } return { value: p.onBattery ? 'Bateria' : 'Tomada', detail: p.onBattery ? 'Na bateria, o Windows segura o desempenho.' : 'Sem limite de energia da bateria.', tone: p.onBattery ? 'warn' : 'good' }; } },
    { id: 'custo-nexo', icon: 'leaf', title: 'Custo do Nexo agora', needs: ['self'], compute: (c) => { const s = c.src('self'); if (!s) { return null; } return { value: H.nf(s.cpu, 1), unit: '% CPU', detail: `${H.bytes(s.memMB * 1024 * 1024)} de memória em ${H.plural(s.processes, 'processo', 'processos')}`, tone: H.tone(s.cpu, 5, 12) }; } },
    { id: 'ontem-agora', icon: 'calendar', title: 'Comparado a ontem, nesta hora', compute: (c) => { const now = Date.now(); const y = H.vals(c.hist.filter((s) => s.timestamp >= now - DAY - 30 * 60e3 && s.timestamp <= now - DAY + 30 * 60e3), 'cpu'); const t = H.vals(c.since(30 * 60e3), 'cpu'); if (y.length < 5 || t.length < 3) { return null; } const d = H.avg(t) - H.avg(y); return { value: `${H.signed(d)}`, unit: 'pontos', detail: `Hoje ${H.nf(H.avg(t))}% · ontem ${H.nf(H.avg(y))}% de CPU`, tone: d > 20 ? 'warn' : 'good' }; } },
    { id: 'ceu', icon: 'moon', title: 'Céu de agora', compute: () => { const h = Nexo.skyHour?.() || 'noite'; return { value: { anoitecer: 'Anoitecer', noite: 'Noite', madrugada: 'Madrugada', amanhecer: 'Amanhecer', dia: 'Dia' }[h], detail: 'O tom do céu acompanha a hora (Ajustes > Aparência).' }; }, kind: 'ferramenta', action: { label: 'Meteoros', run: () => { Nexo.sky?.shower(); return Nexo.effectsLite ? 'O modo Leve está ligado: o céu fica parado.' : ''; } } },
    { id: 'gerenciador', icon: 'list', title: 'Gerenciador de Tarefas', kind: 'acao', os: 'win32', compute: () => ({ value: 'Abrir', detail: 'Para ver tudo o que está rodando.' }), action: { label: 'Abrir', run: async () => { await bridge.openTaskManager(); } } },
    { id: 'copiar-resumo', icon: 'copy', title: 'Copiar resumo do PC', kind: 'ferramenta', compute: (c) => (c.snap ? { value: 'Pronto', detail: 'Processador, memória, discos, sistema e leituras de agora, em texto.' } : null), action: { label: 'Copiar', run: async (c) => { const s = c.snap; const diskLine = (d) => { const model = d.model ? ` · ${d.model}` : ''; return `Disco ${d.name}: ${H.bytes(d.freeBytes)} livres de ${H.bytes(d.sizeBytes)}${model}`; }; const text = [`${s.hostname} · ${s.operatingSystem}`, `Processador: ${s.cpuModel} (${s.logicalCpuCount} threads) · ${H.nf(s.cpuUsage)}% agora`, `Memória: ${H.bytes(s.memoryUsedBytes)} de ${H.bytes(s.memoryTotalBytes)} (${s.memoryPercent}%)`, ...(s.drives || []).map(diskLine), `Ligado há ${H.dur(s.uptimeSeconds)} · Nexo ${s.version}`].join('\n'); return (await H.copy(text)) ? 'Resumo copiado.' : 'Não consegui copiar.'; } } },
    { id: 'threads', icon: 'layers', title: 'Carga por thread', compute: (c) => { const s = c.snap; if (!s?.logicalCpuCount || !H.fin(s.cpuUsage)) { return null; } const busy = (s.cpuUsage / 100) * s.logicalCpuCount; return { value: H.nf(busy, 1), unit: `de ${s.logicalCpuCount}`, detail: 'Threads ocupadas em média agora', bar: s.cpuUsage / 100 }; } },
    { id: 'analise-rapida', icon: 'rocket', title: 'Análise rápida', kind: 'acao', compute: () => ({ value: 'Rodar', detail: 'Mede tudo de novo e atualiza as observações.' }), action: { label: 'Analisar', run: clickId('run-quick', 'analysis') } }
  ]);

  /* ======================= Análise ======================= */
  const grid = (c, metric) => c.brain?.habitGrid?.(metric) || { grid: [], max: 0 };
  const cells = (c, metric) => grid(c, metric).grid.flatMap((row, day) => row.map((v, hour) => ({ day, hour, v }))).filter((cell) => H.fin(cell.v));
  const cellLabel = (cell) => `${H.weekday(cell.day)}, ${String(cell.hour).padStart(2, '0')}h`;
  const episodes = (c, kind, ms = 7 * DAY) => c.brain?.recentEpisodes?.(ms, Date.now(), kind ? [kind] : null) || [];
  const minutesAbove = (list, key, limit) => list.filter((s) => H.fin(s[key]) && s[key] >= limit).length;
  add('analysis', [
    { id: 'hora-pesada', icon: 'fire', title: 'Hora mais pesada da semana', empty: 'Aprendendo', compute: (c) => { const l = cells(c, 'cpu'); if (l.length < 6) { return null; } const [top] = l.sort((a, b) => b.v - a.v); return { value: cellLabel(top), text: true, detail: `CPU média de ${H.nf(top.v)}% nesse horário` }; } },
    { id: 'hora-leve', icon: 'leaf', title: 'Hora mais leve da semana', empty: 'Aprendendo', compute: (c) => { const l = cells(c, 'cpu'); if (l.length < 6) { return null; } const [low] = l.sort((a, b) => a.v - b.v); return { value: cellLabel(low), text: true, detail: `CPU média de ${H.nf(low.v)}%` }; } },
    { id: 'dia-pesado', icon: 'calendar', title: 'Dia mais pesado', empty: 'Aprendendo', compute: (c) => { const g = grid(c, 'cpu').grid; const days = g.map((row, day) => ({ day, v: H.avg(row.filter(H.fin)) })).filter((d) => H.fin(d.v)); if (days.length < 2) { return null; } const [top] = days.sort((a, b) => b.v - a.v); return { value: H.weekday(top.day), detail: `CPU média de ${H.nf(top.v)}% ao longo do dia`, list: days.slice(1, 3).map((d) => [H.weekday(d.day), `${H.nf(d.v)}%`]) }; } },
    { id: 'cobertura', icon: 'star', title: 'Semana conhecida', compute: (c) => { const l = c.brain?.learning?.(); return l ? { value: H.nf(l.coverage), unit: '%', detail: 'das 168 horas da semana já têm padrão', bar: l.coverage / 100 } : null; } },
    { id: 'dias-historico', icon: 'history', title: 'Dias de histórico', compute: (c) => { if (!c.hist.length) { return null; } const span = (Date.now() - c.hist[0].timestamp) / DAY; return { value: H.nf(span, 1), unit: 'dias', detail: `${H.nf(c.hist.length)} minutos guardados (até 7 dias)` }; } },
    { id: 'minutos', icon: 'timer', title: 'Tempo observado', compute: (c) => { const l = c.brain?.learning?.(); if (!l) { return null; } const since = l.days ? `, há ${l.days} dias` : ''; return { value: H.dur(l.minutes * 60), text: true, detail: `desde que o Nexo começou a aprender${since}` }; } },
    { id: 'picos-cpu', icon: 'cpu', title: 'Picos de CPU (7 dias)', compute: (c) => { const e = episodes(c, 'cpu'); return { value: H.nf(e.length), detail: e.length ? `Somam ${H.dur(H.sum(H.vals(e, 'minutes')) * 60)} · último ${H.ago(e[0].end)}` : 'Nenhum pico sustentado.', tone: e.length > 10 ? 'warn' : 'good' }; } },
    { id: 'picos-mem', icon: 'mem', title: 'Memória no limite (7 dias)', compute: (c) => { const e = episodes(c, 'memory'); const culprit = e[0]?.culprit ? ` · ${e[0].culprit}` : ''; return { value: H.nf(e.length), detail: e.length ? `Último ${H.ago(e[0].end)}${culprit}` : 'Nunca faltou memória.', tone: e.length > 3 ? 'warn' : 'good' }; } },
    { id: 'picos-calor', icon: 'temp', title: 'Calor alto (7 dias)', compute: (c) => { const e = episodes(c, 'thermal'); return { value: H.nf(e.length), detail: e.length ? `Pico de ${temp(H.max(H.vals(e, 'peak')))}` : 'Nenhum episódio de calor.', tone: e.length ? 'warn' : 'good' }; } },
    { id: 'quedas-clock', icon: 'bolt', title: 'Quedas de clock (7 dias)', compute: (c) => { const e = episodes(c, 'throttle'); return { value: H.nf(e.length), detail: e.length ? 'O processador desacelerou sob carga.' : 'Nenhuma queda detectada.', tone: e.length ? 'warn' : 'good' }; } },
    { id: 'culpado', icon: 'target', title: 'Quem mais causa lentidão', empty: 'Ninguém ainda', compute: (c) => { const l = c.brain?.ledger?.() || []; if (!l.length) { return null; } return { value: l[0].name, text: true, detail: `${H.plural(l[0].events, 'vez', 'vezes')} · ${H.dur(l[0].minutes * 60)} no total`, list: l.slice(1, 3).map((e) => [e.name, `${e.events}×`]) }; } },
    { id: 'avaliacoes', icon: 'heart', title: 'Suas avaliações', compute: (c) => { const f = c.feedback; if (!f.length) { return { value: '0', detail: 'Marque se uma observação ajudou: o Nexo aprende com isso.' }; } const good = f.filter((e) => e.helpful).length; return { value: H.nf(f.length), detail: `${H.nf((good / f.length) * 100)}% marcadas como úteis`, bar: good / f.length }; } },
    { id: 'cpu-p95', icon: 'cpu', title: 'CPU no pior 5% do dia', compute: (c) => { const v = H.vals(c.since(DAY), 'cpu'); if (v.length < 30) { return null; } const p = H.pct(v, 95); return { value: H.nf(p), unit: '%', detail: `Mediana de ${H.nf(H.pct(v, 50))}% · 24 h`, tone: H.tone(p, 80, 95) }; } },
    { id: 'mem-p95', icon: 'mem', title: 'Memória no pior 5% do dia', compute: (c) => { const v = H.vals(c.since(DAY), 'memory'); if (v.length < 30) { return null; } const p = H.pct(v, 95); return { value: H.nf(p), unit: '%', detail: `Mediana de ${H.nf(H.pct(v, 50))}%`, tone: H.tone(p, 85, 95) }; } },
    { id: 'temp-p95', icon: 'temp', title: 'Temperatura no pior 5% do dia', compute: (c) => { const v = c.since(DAY).map((s) => c.hottest(s)).filter(H.fin); if (v.length < 30) { return null; } const p = H.pct(v, 95); return { value: temp(p), detail: `Mediana de ${temp(H.pct(v, 50))}`, tone: H.tone(p, 85, 95) }; } },
    { id: 'gpu-24h', icon: 'gpu', title: 'Placa de vídeo em 24 h', empty: 'Sem sensor', compute: (c) => { const v = H.vals(c.since(DAY), 'gpu'); if (v.length < 10) { return null; } return { value: H.nf(H.avg(v)), unit: '%', detail: `Pico de ${H.nf(H.max(v))}%`, spark: v.filter((_, i) => i % 15 === 0) }; } },
    { id: 'cpu-acima-80', icon: 'fire', title: 'Tempo com CPU acima de 80%', compute: (c) => { const h = c.since(DAY); if (h.length < 30) { return null; } const m = minutesAbove(h, 'cpu', 80); return { value: H.dur(m * 60), text: true, detail: 'nas últimas 24 h', tone: m > 120 ? 'warn' : 'good' }; } },
    { id: 'mem-acima-90', icon: 'mem', title: 'Tempo com memória acima de 90%', compute: (c) => { const h = c.since(DAY); if (h.length < 30) { return null; } const m = minutesAbove(h, 'memory', 90); return { value: H.dur(m * 60), text: true, detail: 'nas últimas 24 h', tone: m > 30 ? 'warn' : 'good' }; } },
    { id: 'tempo-quente', icon: 'temp', title: 'Tempo acima de 85 °C', compute: (c) => { const h = c.since(DAY); if (h.length < 30) { return null; } const m = h.filter((s) => (c.hottest(s) ?? 0) >= 85).length; return { value: H.dur(m * 60), text: true, detail: 'nas últimas 24 h', tone: m > 30 ? 'warn' : 'good' }; } },
    { id: 'mem-tendencia', icon: 'chart', title: 'Memória ao longo da semana', compute: (c) => { const pts = c.hist.filter((_, i) => i % 30 === 0).map((s) => [s.timestamp / DAY, s.memory]).filter(([, v]) => H.fin(v)); if (pts.length < 12) { return null; } const slope = H.slope(pts); return { value: `${H.signed(slope, 1)}`, unit: 'pontos/dia', detail: Math.abs(slope) < 1 ? 'Estável: o uso não está crescendo.' : slope > 0 ? 'Crescendo: algo pode estar acumulando.' : 'Diminuindo.', tone: slope > 3 ? 'warn' : 'good', spark: pts.map((p) => p[1]) }; } },
    { id: 'disco-ritmo', icon: 'disk', title: 'Ritmo de ocupação do disco', empty: 'Aprendendo', compute: () => { const f = forecast(); return f ? { value: `${H.signed(f.slopePerDay, 2)}`, unit: 'pontos/dia', detail: `Confiança da tendência: ${H.nf(f.r2 * 100)}%`, tone: f.slopePerDay > 1 ? 'warn' : 'good' } : null; } },
    { id: 'horas-dia', icon: 'clock', title: 'Horas ligado por dia', compute: (c) => { if (c.hist.length < 60) { return null; } const span = Math.max(1, (Date.now() - c.hist[0].timestamp) / DAY); return { value: H.nf(Math.min(24, c.hist.length / 60 / span), 1), unit: 'h', detail: 'média com o Nexo aberto' }; } },
    { id: 'faixa-normal', icon: 'target', title: 'Faixa normal desta hora', empty: 'Aprendendo', compute: (c) => { const e = c.brain?.expected?.('cpu', Date.now()); if (!e) { return null; } return { value: `${H.nf(Math.max(0, e.mean - e.sd))}–${H.nf(Math.min(100, e.mean + e.sd))}`, unit: '%', detail: `Baseado em ${H.plural(e.n, 'minuto', 'minutos')} neste horário` }; } },
    { id: 'hora-jogar', icon: 'game', title: 'Melhor hora para jogar', empty: 'Aprendendo', compute: (c) => { const l = cells(c, 'cpu').filter((x) => x.hour >= 17 || x.hour <= 1); if (l.length < 4) { return null; } const [best] = l.sort((a, b) => a.v - b.v); return { value: cellLabel(best), text: true, detail: `Menos coisas rodando em segundo plano (${H.nf(best.v)}% de CPU)` }; } },
    { id: 'hora-manutencao', icon: 'broom', title: 'Melhor hora para manutenção', empty: 'Aprendendo', compute: (c) => { const l = cells(c, 'cpu').filter((x) => x.hour >= 7 && x.hour <= 23); if (l.length < 4) { return null; } const [best] = l.sort((a, b) => a.v - b.v); return { value: cellLabel(best), text: true, detail: 'Com o PC ligado e quieto: bom para limpar e otimizar.' }; } },
    { id: 'hoje-vs-semana', icon: 'chart', title: 'Hoje vs a semana', compute: (c) => { const start = new Date(); start.setHours(0, 0, 0, 0); const today = H.vals(c.hist.filter((s) => s.timestamp >= start.getTime()), 'cpu'); const week = H.vals(c.hist.filter((s) => s.timestamp < start.getTime()), 'cpu'); if (today.length < 10 || week.length < 60) { return null; } const d = H.avg(today) - H.avg(week); return { value: `${H.signed(d)}`, unit: 'pontos', detail: `CPU média: hoje ${H.nf(H.avg(today))}%, resto da semana ${H.nf(H.avg(week))}%`, tone: d > 15 ? 'warn' : 'good' }; } },
    { id: 'confianca', icon: 'shield', title: 'Confiança nesta hora', empty: 'Aprendendo', compute: (c) => { const e = c.brain?.expected?.('cpu', Date.now()); if (!e) { return null; } const k = Math.min(1, e.n / 120); return { value: k > 0.75 ? 'Alta' : k > 0.35 ? 'Média' : 'Baixa', detail: `${H.plural(e.n, 'minuto medido', 'minutos medidos')} nesta hora da semana`, bar: k }; } },
    { id: 'gpu-calor', icon: 'gpu', title: 'Placa de vídeo mais quente (24 h)', empty: 'Sem sensor', compute: (c) => { const v = H.vals(c.since(DAY), 'gpuTemperature'); if (v.length < 10) { return null; } const m = H.max(v); return { value: temp(m), detail: `Média de ${temp(H.avg(v))}`, tone: H.tone(m, 83, 90) }; } },
    { id: 'exportar-historico', icon: 'download', title: 'Exportar histórico (CSV)', kind: 'ferramenta', compute: (c) => (c.hist.length ? { value: H.plural(c.hist.length, 'minuto', 'minutos'), text: true, detail: 'CPU, memória, disco, vídeo e temperaturas, um por minuto.' } : null), action: { label: 'Baixar', run: (c) => { const rows = [['data', 'cpu', 'memoria', 'disco', 'gpu', 'temp_cpu', 'temp_gpu', 'temp_acpi'], ...c.hist.map((s) => [new Date(s.timestamp).toISOString(), s.cpu, s.memory, s.disk, s.gpu, s.cpuSensorTemperature, s.gpuTemperature, s.acpiTemperature].map((v) => (v === null || v === undefined ? '' : String(v).replace('.', ','))))]; H.download(`nexo-historico-${H.stamp()}.csv`, rows.map((r) => r.join(';')).join('\n'), 'text/csv'); return 'Histórico exportado.'; } } },
    { id: 'reanalisar', icon: 'rocket', title: 'Análise profunda', kind: 'acao', compute: () => ({ value: 'Rodar', detail: 'Peças, eventos, o que roda por trás e um teste de carga (1 a 2 min).' }), action: { label: 'Analisar', run: clickId('run-diagnosis', 'analysis') } }
  ]);

  /* ======================= Hardware ======================= */
  const facts = (c) => c.src('facts');
  add('hardware', [
    { id: 'cpu-modelo', icon: 'cpu', title: 'Processador', compute: (c) => (c.snap ? { value: c.snap.cpuModel.replace(/\s+/g, ' ').trim(), text: true, detail: `${c.snap.logicalCpuCount} threads lógicas` } : null) },
    { id: 'cpu-temp-max', icon: 'temp', title: 'Processador: mais quente desde que abriu', empty: 'Sem sensor', compute: (c) => { const l = byType(c, ['Cpu'], 'Temperature', okTemp); const max = H.max(l.map((s) => s.max).filter((v) => H.fin(v) && v < 125)); if (!H.fin(max)) { return null; } return { value: temp(max), detail: `Agora: ${temp(H.max(H.vals(l, 'value')))}`, tone: H.tone(max, 88, 95) }; } },
    { id: 'cpu-clock-max', icon: 'bolt', title: 'Maior clock atingido', empty: 'Sem sensor', compute: (c) => { const l = byType(c, ['Cpu'], 'Clock', (s) => /core/i.test(s.name) && !/bus/i.test(s.name)); const max = H.max(H.vals(l, 'max')); if (!H.fin(max)) { return null; } return { value: H.nf(max / 1000, 2), unit: 'GHz', detail: `${l.length} núcleos com leitura` }; } },
    { id: 'cpu-clock-medio', icon: 'wave', title: 'Clock médio dos núcleos', empty: 'Sem sensor', compute: (c) => { const l = byType(c, ['Cpu'], 'Clock', (s) => /core/i.test(s.name) && !/bus|effective/i.test(s.name)); if (!l.length) { return null; } const v = H.vals(l, 'value'); return { value: H.nf(H.avg(v) / 1000, 2), unit: 'GHz', detail: `Do mais lento (${H.nf(H.min(v) / 1000, 2)}) ao mais rápido (${H.nf(H.max(v) / 1000, 2)})` }; } },
    { id: 'cpu-nucleo-quente', icon: 'fire', title: 'Núcleo mais quente', empty: 'Sem sensor', compute: (c) => { const l = byType(c, ['Cpu'], 'Temperature', (s) => okTemp(s) && /core|ccd|tdie|tctl/i.test(s.name)); if (!l.length) { return null; } const [top] = l.sort((a, b) => b.value - a.value); return { value: temp(top.value), detail: top.name, tone: H.tone(top.value, 85, 95) }; } },
    { id: 'cpu-potencia', icon: 'plug', title: 'Consumo do processador', empty: 'Sem sensor', compute: (c) => { const l = byType(c, ['Cpu'], 'Power', (s) => /package|cpu/i.test(s.name)); if (!l.length) { return null; } const [p] = l.sort((a, b) => b.value - a.value); return { value: H.nf(p.value, 1), unit: 'W', detail: H.fin(p.max) ? `Máximo visto: ${H.nf(p.max, 1)} W` : p.name }; } },
    { id: 'cpu-tensao', icon: 'pulse', title: 'Tensão do núcleo', empty: 'Sem sensor', compute: (c) => { const l = byType(c, ['Cpu', 'SuperIO', 'Motherboard'], 'Voltage', (s) => /core|vcore|vid/i.test(s.name) && s.value > 0.3 && s.value < 2); if (!l.length) { return null; } return { value: H.nf(l[0].value, 3), unit: 'V', detail: l[0].name }; } },
    { id: 'gpu-modelo', icon: 'gpu', title: 'Placa de vídeo', empty: 'Não detectada', compute: (c) => { const d = c.devices().find((x) => gpuTypes.includes(x.type)); const f = facts(c)?.displays?.[0]?.name; const name = d?.name || f; return name ? { value: name, text: true, detail: c.devices().filter((x) => gpuTypes.includes(x.type)).length > 1 ? 'Mais de uma placa detectada' : 'Placa principal' } : null; }, needs: ['facts'] },
    { id: 'gpu-quente', icon: 'temp', title: 'Placa de vídeo: temperatura', empty: 'Sem sensor', compute: (c) => { const l = byType(c, gpuTypes, 'Temperature', okTemp); if (!l.length) { return null; } const core = l.find((s) => /core|gpu$/i.test(s.name)) || l[0]; const hot = l.find((s) => /hot ?spot|junction/i.test(s.name)); return { value: temp(core.value), detail: hot ? `Ponto mais quente: ${temp(hot.value)}` : `Máxima vista: ${temp(core.max)}`, tone: H.tone(hot?.value ?? core.value, 85, 95) }; } },
    { id: 'gpu-clock', icon: 'bolt', title: 'Clock da placa de vídeo', empty: 'Sem sensor', compute: (c) => { const l = byType(c, gpuTypes, 'Clock', (s) => /core|graphics|shader/i.test(s.name)); if (!l.length) { return null; } return { value: H.nf(l[0].value), unit: 'MHz', detail: H.fin(l[0].max) ? `Máximo visto: ${H.nf(l[0].max)} MHz` : l[0].name }; } },
    { id: 'gpu-vram', icon: 'mem', title: 'Memória de vídeo em uso', empty: 'Sem sensor', compute: (c) => { const [used] = byType(c, gpuTypes, 'SmallData', (s) => /memory used|d3d dedicated memory used/i.test(s.name)); const [total] = byType(c, gpuTypes, 'SmallData', (s) => /memory total/i.test(s.name)); const smi = c.snap?.temperatureReadings?.gpuSensors?.[0]; const u = used?.value ?? smi?.memoryUsedMb; const t = total?.value ?? smi?.memoryTotalMb; if (!H.fin(u)) { return null; } return { value: H.bytes(u * 1024 * 1024), detail: H.fin(t) ? `de ${H.bytes(t * 1024 * 1024)}` : 'usada agora', bar: H.fin(t) && t ? u / t : undefined, tone: H.fin(t) && t ? H.tone(u / t, 0.85, 0.95) : undefined }; } },
    { id: 'gpu-potencia', icon: 'plug', title: 'Consumo da placa de vídeo', empty: 'Sem sensor', compute: (c) => { const l = byType(c, gpuTypes, 'Power'); if (!l.length) { return null; } const [p] = l.sort((a, b) => b.value - a.value); return { value: H.nf(p.value, 1), unit: 'W', detail: H.fin(p.max) ? `Máximo visto: ${H.nf(p.max, 1)} W` : p.name }; } },
    { id: 'gpu-ventoinha', icon: 'fan', title: 'Ventoinha da placa de vídeo', empty: 'Sem sensor', compute: (c) => { const [rpm] = byType(c, gpuTypes, 'Fan'); const [ctl] = byType(c, gpuTypes, 'Control'); if (!rpm && !ctl) { return null; } return rpm ? { value: H.nf(rpm.value), unit: 'RPM', detail: ctl ? `${H.nf(ctl.value)}% da potência` : rpm.name, tone: rpm.value === 0 ? 'good' : undefined } : { value: H.nf(ctl.value), unit: '%', detail: 'da potência' }; } },
    { id: 'ventoinhas', icon: 'fan', title: 'Ventoinhas do sistema', empty: 'Sem sensor', emptyDetail: 'A placa-mãe não expõe ou o serviço de sensores está desligado.', compute: (c) => { const l = byType(c, ['SuperIO', 'Motherboard', 'EmbeddedController', 'Cooler'], 'Fan', (s) => s.value > 0); if (!l.length) { return null; } return { value: H.nf(l.length), detail: 'girando agora', list: l.slice(0, 4).map((s) => [s.name, `${H.nf(s.value)} RPM`]) }; } },
    { id: 'ram-instalada', icon: 'mem', title: 'Memória instalada', needs: ['facts'], compute: (c) => { const total = c.snap?.memoryTotalBytes; if (!total) { return null; } const mods = facts(c)?.memory || []; return { value: H.bytes(total), detail: mods.length ? `${H.plural(mods.length, 'pente', 'pentes')}: ${mods.map((m) => H.bytes(m.capacity)).join(' + ')}` : 'Pentes não informados' }; } },
    { id: 'ram-velocidade', icon: 'rocket', title: 'Velocidade da memória', needs: ['facts'], os: 'win32', empty: 'Não informada', compute: (c) => { const mods = (facts(c)?.memory || []).filter((m) => H.fin(m.speed) && m.speed > 0); if (!mods.length) { return null; } const rated = H.max(H.vals(mods, 'speed')); const conf = H.min(H.vals(mods, (m) => m.configured || m.speed)); const low = conf < rated * 0.9; return { value: H.nf(conf), unit: 'MT/s', detail: low ? `Os pentes aceitam ${H.nf(rated)} MT/s: o perfil XMP/EXPO pode estar desligado na BIOS.` : 'Rodando na velocidade informada pelos pentes.', tone: low ? 'warn' : 'good' }; } },
    { id: 'canais', icon: 'layers', title: 'Canais de memória', needs: ['facts'], os: 'win32', empty: 'Não informado', compute: (c) => { const mods = facts(c)?.memory || []; if (!mods.length) { return null; } return mods.length === 1 ? { value: 'Provável 1 canal', text: true, detail: 'Só um pente detectado: dois pentes iguais costumam render mais (exceto memória soldada).', tone: 'warn' } : { value: 'Provável 2 canais', text: true, detail: `${mods.length} pentes detectados (depende dos slots usados).`, tone: 'good' }; } },
    { id: 'monitores', icon: 'screen', title: 'Taxa de atualização', needs: ['facts'], os: 'win32', empty: 'Não informada', compute: (c) => { const d = (facts(c)?.displays || []).filter((x) => H.fin(x.current) && x.current > 1); if (!d.length) { return null; } const low = d.find((x) => x.current <= 60 && H.fin(x.max) && x.max >= 100); return { value: d.map((x) => `${x.current} Hz`).join(' · '), text: true, detail: low ? `A placa aceita até ${low.max} Hz: confira se o monitor está na taxa máxima.` : 'Taxa atual de cada saída de vídeo.', tone: low ? 'warn' : 'good' }; }, action: { label: 'Ajustar', when: (c) => Nexo.platform === 'win32', run: async () => { await bridge.openWindowsSettings('display'); } } },
    { id: 'discos', icon: 'disk', title: 'Discos', compute: (c) => { const d = c.snap?.drives || []; if (!d.length) { return null; } return { value: H.plural(d.length, 'unidade', 'unidades'), text: true, detail: `${H.bytes(H.sum(H.vals(d, 'sizeBytes')))} no total`, list: d.slice(0, 4).map((x) => [x.name, x.media || x.bus || x.fileSystem]) }; } },
    { id: 'ssd-temp', icon: 'temp', title: 'Disco mais quente', empty: 'Sem sensor', compute: (c) => { const l = byType(c, ['Storage'], 'Temperature', okTemp); if (!l.length) { return null; } const [top] = l.sort((a, b) => b.value - a.value); return { value: temp(top.value), detail: top.device, tone: H.tone(top.value, 60, 70) }; } },
    { id: 'ssd-vida', icon: 'heart', title: 'Vida útil do SSD', empty: 'Não informada', emptyDetail: 'Nem todo SSD informa o desgaste.', compute: (c) => { const [used] = byType(c, ['Storage'], 'Level', (s) => /percentage used|wear|used endurance/i.test(s.name)); const [life] = byType(c, ['Storage'], 'Level', (s) => /life|remaining/i.test(s.name)); if (!used && !life) { return null; } const left = life ? life.value : 100 - used.value; return { value: H.nf(left), unit: '%', detail: `restante · ${(used || life).device}`, bar: left / 100, tone: H.tone(left, 30, 10, false) }; } },
    { id: 'ssd-gravado', icon: 'download', title: 'Dados já gravados no SSD', empty: 'Não informado', compute: (c) => { const l = byType(c, ['Storage'], 'Data', (s) => /written|host writes/i.test(s.name)); if (!l.length) { return null; } const [top] = l.sort((a, b) => b.value - a.value); return { value: H.bytes(top.value * 1024 ** 3), detail: top.device }; } },
    { id: 'placa-mae', icon: 'layers', title: 'Placa-mãe', empty: 'Não informada', compute: (c) => { const d = c.devices().find((x) => x.type === 'Motherboard'); return d ? { value: d.name, text: true, detail: `${c.devices().filter((x) => x.type === 'SuperIO').length ? 'Com chip de sensores (Super I/O)' : 'Sem chip de sensores exposto'}` } : null; } },
    { id: 'sensores-total', icon: 'eye', title: 'Sensores lidos', empty: 'Serviço desligado', compute: (c) => { const l = c.sensors(); if (!l.length) { return null; } return { value: H.nf(l.length), detail: `em ${H.plural(c.devices().length, 'componente', 'componentes')}`, list: H.count(l, (s) => s.type).slice(0, 3).map(([k, v]) => [k, v]) }; } },
    { id: 'limites', icon: 'shield', title: 'Limites do fabricante', empty: 'Nenhum informado', compute: (c) => { const l = c.sensors().filter((s) => s.type === 'Temperature' && LIMIT.test(String(s.name)) && H.fin(s.value) && s.value > 0); if (!l.length) { return null; } return { value: H.plural(l.length, 'limite', 'limites'), text: true, detail: 'Valores fixos: não são leitura de temperatura.', list: l.slice(0, 3).map((s) => [`${s.device.split(' ').slice(-1)[0]} · ${s.name}`, temp(s.value)]) }; } },
    { id: 'bateria', icon: 'battery', title: 'Bateria', empty: 'Sem bateria', emptyDetail: 'Desktop ou bateria não exposta.', compute: (c) => { const l = byType(c, ['Battery'], 'Level', (s) => /charge/i.test(s.name)); const [wear] = byType(c, ['Battery'], 'Level', (s) => /degradation|wear/i.test(s.name)); if (!l.length) { return null; } return { value: H.nf(l[0].value), unit: '%', detail: wear ? `Desgaste: ${H.nf(wear.value)}%` : 'Carga atual', bar: l[0].value / 100 }; } },
    { id: 'rede-trafego', icon: 'globe', title: 'Tráfego de rede agora', empty: 'Sem sensor', compute: (c) => { const up = byType(c, ['Network'], 'Throughput', (s) => /upload/i.test(s.name)); const down = byType(c, ['Network'], 'Throughput', (s) => /download/i.test(s.name)); if (!up.length && !down.length) { return null; } return { value: `${H.bytes(H.sum(H.vals(down, 'value')))}/s`, text: true, detail: `↓ recebendo · ↑ ${H.bytes(H.sum(H.vals(up, 'value')))}/s enviando` }; } },
    { id: 'vbs', icon: 'lock', title: 'Segurança por virtualização', needs: ['facts'], os: 'win32', empty: 'Não informado', compute: (c) => { const f = facts(c); if (f?.vbs === undefined || f?.vbs === null) { return null; } return { value: f.vbs === 2 ? 'Ligada' : 'Desligada', detail: f.vbs === 2 ? `${f.hvci ? 'Com Integridade de memória. ' : ''}Proteção do Windows: o Nexo não mexe.` : 'O Windows não está usando VBS.' }; } },
    { id: 'hags', icon: 'gpu', title: 'Agendamento de GPU acelerado', needs: ['facts'], os: 'win32', empty: 'Não informado', compute: (c) => { const h = facts(c)?.hags; if (h !== 1 && h !== 2) { return null; } return { value: h === 2 ? 'Ligado' : 'Desligado', detail: 'O Raio-X e o Extremo testam se faz diferença aqui.' }; }, action: { label: 'Abrir', when: () => Nexo.platform === 'win32', run: async () => { await bridge.openWindowsSettings('graphics'); } } },
    { id: 'copiar-specs', icon: 'copy', title: 'Copiar especificações', kind: 'ferramenta', needs: ['facts'], compute: (c) => (c.snap ? { value: 'Pronto', detail: 'Para mandar num fórum ou para um amigo.' } : null), action: { label: 'Copiar', run: async (c) => {
      const s = c.snap; const f = facts(c) || {};
      const gpu = c.devices().filter((x) => gpuTypes.includes(x.type)).map((x) => x.name);
      const sticks = (f.memory || []).length ? ` (${f.memory.length} pentes, ${H.max(H.vals(f.memory, 'configured')) || '?'} MT/s)` : '';
      const diskLine = (d) => { const model = d.model ? `· ${d.model}` : ''; const media = d.media ? `(${d.media})` : ''; return `Disco ${d.driveLetter}: ${H.bytes(d.sizeBytes)} ${model} ${media}`; };
      const hz = (d) => `${d.current} Hz`;
      const lines = [`Processador: ${s.cpuModel} (${s.logicalCpuCount} threads)`, `Placa de vídeo: ${gpu.join(', ') || (f.displays || []).map((d) => d.name).join(', ') || 'não detectada'}`, `Memória: ${H.bytes(s.memoryTotalBytes)}${sticks}`, `Placa-mãe: ${c.devices().find((x) => x.type === 'Motherboard')?.name || 'não informada'}`, ...(s.drives || []).map(diskLine), `Monitores: ${(f.displays || []).map(hz).join(', ') || '?'}`, `Sistema: ${s.operatingSystem}`]; return (await H.copy(lines.join('\n'))) ? 'Especificações copiadas.' : 'Não consegui copiar.'; } } },
    { id: 'exportar-sensores', icon: 'download', title: 'Exportar sensores (JSON)', kind: 'ferramenta', empty: 'Sem leitura', compute: (c) => (c.sensors().length ? { value: H.plural(c.sensors().length, 'sensor', 'sensores'), text: true, detail: 'Com mínimo, máximo e unidade de cada um.' } : null), action: { label: 'Baixar', run: (c) => { H.download(`nexo-sensores-${H.stamp()}.json`, JSON.stringify(c.devices(), null, 2)); return 'Sensores exportados.'; } } }
  ]);

  /* ======================= Manutenção ======================= */
  const drives = (c) => c.snap?.drives || [];
  add('maintenance', [
    { id: 'quase-cheios', icon: 'disk', title: 'Unidades quase cheias', compute: (c) => { const d = drives(c); if (!d.length) { return null; } const full = d.filter((x) => x.usedPercent >= 90); return { value: H.nf(full.length), detail: full.length ? full.map((x) => `${x.driveLetter}: ${x.usedPercent}%`).join(' · ') : 'Todas com mais de 10% livres.', tone: full.length ? 'warn' : 'good' }; } },
    { id: 'mais-livre', icon: 'disk', title: 'Unidade com mais espaço', compute: (c) => { const d = drives(c); if (!d.length) { return null; } const [top] = [...d].sort((a, b) => b.freeBytes - a.freeBytes); return { value: H.bytes(top.freeBytes), detail: `livres em ${top.name}`, bar: top.usedPercent / 100 }; } },
    { id: 'armazenamento-total', icon: 'layers', title: 'Armazenamento total', compute: (c) => { const d = drives(c); if (!d.length) { return null; } const size = H.sum(H.vals(d, 'sizeBytes')); const free = H.sum(H.vals(d, 'freeBytes')); return { value: H.bytes(size), detail: `${H.bytes(free)} livres somando ${H.plural(d.length, 'unidade', 'unidades')}`, bar: 1 - free / size }; } },
    { id: 'tipo-sistema', icon: 'rocket', title: 'Disco do sistema', compute: (c) => { const d = c.snap?.primaryDrive; if (!d) { return null; } const kind = /nvme/i.test(d.bus || '') ? 'SSD NVMe' : /ssd/i.test(d.media || '') ? 'SSD SATA' : /hdd/i.test(d.media || '') ? 'HD' : d.media || 'Desconhecido'; return { value: kind, text: true, detail: d.model || d.name, tone: kind === 'HD' ? 'warn' : 'good' }; } },
    { id: 'sistemas-arquivo', icon: 'folder', title: 'Sistemas de arquivos', compute: (c) => { const d = drives(c); if (!d.length) { return null; } return { value: [...new Set(d.map((x) => x.fileSystem))].join(' · '), text: true, list: d.slice(0, 4).map((x) => [x.name, x.fileSystem]) }; } },
    { id: 'cheio-em', icon: 'calendar', title: 'Disco do sistema cheio em', empty: 'Aprendendo', compute: () => { const f = forecast(); if (!f) { return null; } return f.daysToFull ? { value: H.nf(f.daysToFull), unit: 'dias', detail: 'no ritmo atual', tone: H.tone(f.daysToFull, 30, 10, false) } : { value: 'Sem pressa', detail: 'O uso não está crescendo de forma firme.', tone: 'good' }; } },
    { id: 'ultima-limpeza-m', icon: 'broom', title: 'Última limpeza segura', compute: (c) => { const a = lastActivity(c, /limpeza/i); return a ? { value: H.ago(a.timestamp), detail: a.detail || '' } : { value: 'Nunca', detail: 'Temporários, cache e logs antigos. Mostra uma prévia antes.' }; }, action: { label: 'Limpar', run: clickId('run-cleanup', 'optimize') } },
    { id: 'limpezas-feitas', icon: 'history', title: 'Limpezas registradas', compute: (c) => { const l = c.activity.filter((a) => /limpeza/i.test(a.title)); return { value: H.nf(H.sum(l.map((a) => a.count || 1))), detail: 'no histórico de atividades (últimas 20)' }; } },
    { id: 'limpavel-agora', icon: 'broom', title: 'Dá para liberar agora', empty: 'Ainda não medido', emptyDetail: 'Abra Otimizar para medir.', compute: () => { const t = Nexo.state.cleanupTotals; if (!t) { return null; } return { value: H.bytes(t.bytes), detail: `${H.nf(t.fileCount)} arquivos seguros de apagar`, tone: t.bytes > 5 * 1024 ** 3 ? 'warn' : 'good' }; }, action: { label: 'Ver', run: go('optimize') } },
    { id: 'auto-limpeza', icon: 'timer', title: 'Limpeza automática', compute: () => { const on = readJSON(Nexo.keys.autoClean, false) === true; const last = Number(localStorage.getItem(Nexo.keys.autoCleanLastRun)); return { value: on ? 'Ligada' : 'Desligada', detail: on && H.fin(last) && last > 0 ? `Última vez ${H.ago(last)}` : 'Limpa temporários sozinha, uma vez por semana.', tone: on ? 'good' : undefined }; }, action: { label: 'Ajustar', run: go('optimize') } },
    { id: 'inicializacao', icon: 'rocket', title: 'Programas na inicialização', needs: ['startup'], empty: 'Lendo…', compute: (c) => { const l = c.src('startup'); if (!Array.isArray(l)) { return null; } return { value: H.nf(l.length), detail: l.length > 12 ? 'Muitos programas atrasam o início do Windows.' : 'Quantidade razoável.', tone: H.tone(l.length, 12, 20), list: l.slice(0, 3).map((i) => [i.name, '']) }; }, action: { label: 'Gerenciar', when: () => Nexo.platform === 'win32', run: async () => { await bridge.openWindowsSettings('startup'); } } },
    { id: 'inicializacao-onde', icon: 'list', title: 'De onde vêm', needs: ['startup'], empty: 'Lendo…', compute: (c) => { const l = c.src('startup'); if (!Array.isArray(l) || !l.length) { return null; } const groups = H.count(l, (i) => (/hklm|common|alluser/i.test(i.location || '') ? 'Para todos os usuários' : /hkcu|startup/i.test(i.location || '') ? 'Só do seu usuário' : 'Outros')); return { value: H.plural(groups.length, 'origem', 'origens'), text: true, list: groups }; } },
    { id: 'sfc', icon: 'shield', title: 'Verificação dos arquivos do sistema', os: 'win32', compute: (c) => { const a = lastActivity(c, /sfc|arquivos do sistema/i); return a ? { value: H.ago(a.timestamp), detail: a.detail || '' } : { value: 'Nunca', detail: 'Confere e repara arquivos do Windows (pede permissão).' }; }, action: { label: 'Ir', run: go('maintenance') } },
    { id: 'otimizacao-unidade', icon: 'disk', title: 'Última otimização de unidade', os: 'win32', compute: (c) => { const a = lastActivity(c, /otimiza.*unidade|trim|desfrag/i); return a ? { value: H.ago(a.timestamp), detail: a.detail || '' } : { value: 'Nunca pelo Nexo', detail: 'O Windows também faz isso sozinho, toda semana.' }; } },
    { id: 'uptime', icon: 'history', title: 'Ligado sem reiniciar', compute: (c) => { const up = c.snap?.uptimeSeconds; if (!H.fin(up)) { return null; } return { value: H.dur(up), text: true, detail: up > 7 * 86400 ? 'Reiniciar aplica atualizações e limpa a memória.' : 'Tudo bem.', tone: up > 14 * 86400 ? 'bad' : up > 7 * 86400 ? 'warn' : 'good' }; } },
    { id: 'dados-nexo', icon: 'folder', title: 'Dados do Nexo', needs: ['app'], compute: (c) => { const a = c.src('app'); if (!a) { return null; } return { value: H.bytes(a.userDataBytes), detail: 'Histórico, capas, conta e configurações.' }; } },
    { id: 'armazenamento-local', icon: 'layers', title: 'Memória da interface', compute: () => { let bytes = 0; let keys = 0; try { for (let i = 0; i < localStorage.length; i += 1) { const k = localStorage.key(i); keys += 1; bytes += (k.length + (localStorage.getItem(k) || '').length) * 2; } } catch { return null; } return { value: H.bytes(bytes), detail: `${keys} chaves guardadas pela interface (limite de ~5 MB)`, bar: bytes / (5 * 1024 * 1024), tone: H.tone(bytes / (5 * 1024 * 1024), 0.7, 0.9) }; } },
    { id: 'erros-app', icon: 'bug', title: 'Erros do Nexo (7 dias)', needs: ['errors'], compute: (c) => { const l = c.src('errors'); if (!l) { return null; } const list = (l.groups || []).filter((e) => e.level === 'erro' && e.lastAt >= Date.now() - 7 * DAY); const total = H.sum(H.vals(list, 'count')); return { value: H.nf(total), detail: list.length ? `${H.plural(list.length, 'tipo', 'tipos')} · último ${H.ago(H.max(H.vals(list, 'lastAt')))}` : 'Nenhum erro registrado.', tone: total ? 'warn' : 'good' }; }, action: { label: 'Ver', run: () => { Nexo.go('settings'); setTimeout(() => document.getElementById('errors-sheet')?.scrollIntoView({ behavior: 'smooth' }), 150); } } },
    { id: 'pasta-logs', icon: 'folder', title: 'Pasta do registro de erros', kind: 'acao', compute: () => ({ value: 'Abrir', detail: 'Os arquivos .log ficam só neste PC.' }), action: { label: 'Abrir', run: async () => { await bridge.openErrorFolder(); } } },
    { id: 'jogos-espaco', icon: 'game', title: 'Espaço dos jogos', needs: ['games'], compute: (c) => { const g = (c.src('games') || []).filter((x) => x.installed !== false && x.kind !== 'app'); if (!g.length) { return null; } const total = H.sum(H.vals(g, 'sizeBytes')); const disk = H.sum(H.vals(drives(c), 'sizeBytes')); const share = disk ? ` · ${H.nf((total / disk) * 100)}% do armazenamento` : ''; return { value: H.bytes(total), detail: `${H.plural(g.length, 'jogo instalado', 'jogos instalados')}${share}`, bar: disk ? total / disk : undefined }; } },
    { id: 'maior-jogo', icon: 'trophy', title: 'Maior jogo instalado', needs: ['games'], compute: (c) => { const g = (c.src('games') || []).filter((x) => x.installed !== false && x.sizeBytes > 0).sort((a, b) => b.sizeBytes - a.sizeBytes); if (!g.length) { return null; } return { value: H.bytes(g[0].sizeBytes), detail: g[0].name, list: g.slice(1, 3).map((x) => [x.name, H.bytes(x.sizeBytes)]) }; } },
    { id: 'jogos-esquecidos', icon: 'moon', title: 'Jogos parados há 6 meses', needs: ['games'], compute: (c) => { const g = (c.src('games') || []).filter((x) => x.installed !== false && x.kind !== 'app' && x.lastPlayed && x.lastPlayed < Date.now() - 180 * DAY); if (!(c.src('games') || []).length) { return null; } return { value: H.nf(g.length), detail: g.length ? `Ocupam ${H.bytes(H.sum(H.vals(g, 'sizeBytes')))}: candidatos a desinstalar` : 'Nenhum jogo esquecido.' }; } },
    { id: 'disco-quente', icon: 'temp', title: 'Temperatura dos discos', empty: 'Sem sensor', compute: (c) => { const l = byType(c, ['Storage'], 'Temperature', okTemp); if (!l.length) { return null; } return { value: temp(H.max(H.vals(l, 'value'))), detail: 'acima de 70 °C o SSD desacelera', tone: H.tone(H.max(H.vals(l, 'value')), 60, 70), list: l.slice(0, 3).map((s) => [s.device, temp(s.value)]) }; } },
    { id: 'armazenamento-win', icon: 'gear', title: 'Configurações de armazenamento', kind: 'acao', os: 'win32', compute: () => ({ value: 'Abrir', detail: 'Sensor de Armazenamento e arquivos grandes do Windows.' }), action: { label: 'Abrir', run: async () => { await bridge.openWindowsSettings('storage'); } } },
    { id: 'recuperacao', icon: 'shield', title: 'Recuperação do Windows', kind: 'acao', os: 'win32', compute: () => ({ value: 'Abrir', detail: 'Pontos de restauração e reinicialização avançada.' }), action: { label: 'Abrir', run: async () => { await bridge.openWindowsSettings('recovery'); } } },
    { id: 'sensor-servico', icon: 'eye', title: 'Serviço de sensores', needs: ['sensorService'], os: 'win32', compute: (c) => { const s = c.src('sensorService'); if (!s) { return null; } const ok = s.installed && s.running; return { value: ok ? 'Funcionando' : s.installed ? 'Parado' : 'Não instalado', detail: ok ? 'Temperaturas, clocks e ventoinhas completos.' : 'Sem ele, algumas leituras ficam faltando.', tone: ok ? 'good' : 'warn' }; }, action: { label: 'Ver', run: go('hardware') } },
    { id: 'exportar-dados', icon: 'download', title: 'Cópia dos dados da interface', kind: 'ferramenta', compute: () => ({ value: 'Baixar', detail: 'Preferências, sessões, diário e atividade em JSON.' }), action: { label: 'Baixar', run: () => { const out = {}; try { for (let i = 0; i < localStorage.length; i += 1) { const k = localStorage.key(i); if (/^nexo-/.test(k) && k !== Nexo.keys.history) out[k] = localStorage.getItem(k); } } catch { /* sem armazenamento */ } H.download(`nexo-dados-${H.stamp()}.json`, JSON.stringify(out, null, 2)); return 'Cópia baixada (o histórico de 7 dias fica de fora: use Análise e otimização > Exportar).'; } } },
    { id: 'memoria-uso-longo', icon: 'mem', title: 'Memória ao longo do dia', compute: (c) => { const v = H.vals(c.since(DAY), 'memory'); if (v.length < 30) { return null; } return { value: H.nf(H.avg(v)), unit: '%', detail: `de média · mínimo ${H.nf(H.min(v))}%, máximo ${H.nf(H.max(v))}%`, spark: v.filter((_, i) => i % 20 === 0) }; } },
    { id: 'gerenciador-m', icon: 'list', title: 'Gerenciador de Tarefas', kind: 'acao', os: 'win32', compute: () => ({ value: 'Abrir', detail: 'Programas, serviços e desempenho do Windows.' }), action: { label: 'Abrir', run: async () => { await bridge.openTaskManager(); } } },
    { id: 'checklist', icon: 'list', title: 'Checklist de manutenção', compute: (c) => { const items = [['Limpeza no último mês', Boolean(lastActivity(c, /limpeza/i)) && Date.now() - lastActivity(c, /limpeza/i).timestamp < 30 * DAY], ['Reiniciado na última semana', (c.snap?.uptimeSeconds || 0) < 7 * 86400], ['Disco do sistema abaixo de 85%', (c.snap?.primaryDrive?.usedPercent || 0) < 85], ['Sem erros do Nexo', true]]; const done = items.filter((i) => i[1]).length; return { value: `${done} de ${items.length}`, text: true, bar: done / items.length, list: items.map(([k, v]) => [k, v ? '✓' : '—']), tone: done === items.length ? 'good' : 'warn' }; } }
  ]);
})();
